begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('10000000-0000-0000-0000-000000000001','stage2-a@example.test',now()),
 ('10000000-0000-0000-0000-000000000002','stage2-b@example.test',now()),
 ('10000000-0000-0000-0000-000000000003','stage2-c@example.test',now()),
 ('10000000-0000-0000-0000-000000000004','stage2-unconfirmed@example.test',null);
create temp table test_ids(label text primary key,id uuid);
grant all on test_ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
select throws_ok($$select public.complete_onboarding('Pessoa Teste','2000-01-01',true,'Teste','test_unconfirmed','São Paulo','SP')$$,null,'Confirme seu e-mail antes de continuar.','email não confirmado não conclui onboarding');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.complete_onboarding('Pessoa A',((now() at time zone 'America/Sao_Paulo')::date - interval '17 years')::date,true,'Pessoa A','test_a','São Paulo','SP')$$,null,'Cadastro permitido somente para maiores de 18 anos.','servidor rejeita 17 anos');
select throws_ok($$select public.complete_onboarding('Pessoa A','2000-01-01',false,'Pessoa A','test_a','São Paulo','SP')$$,null,'Cadastro permitido somente para maiores de 18 anos.','confirmação explícita obrigatória');
insert into test_ids values('a',public.complete_onboarding('Nome Civil A','2000-01-01',true,'Pessoa A','test_a','São Paulo','SP'));
select is((select count(*) from public.users_private),1::bigint,'A lê apenas seus dados privados');
select throws_ok($$update public.users_private set birth_date='2020-01-01'$$,'42501',null,'cliente não altera nascimento');
select throws_ok($$insert into public.profiles(type,nickname,username,city,state) values('couple','Fraude','fake_couple','São Paulo','SP')$$,'42501',null,'cliente não fabrica casal');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
insert into test_ids values('b',public.complete_onboarding('Nome Civil B','2001-01-01',true,'Pessoa B','test_b','São Paulo','SP'));
select is((select count(*) from public.users_private where legal_name='Nome Civil A'),0::bigint,'B não lê nome civil ou nascimento de A');
select is((select count(*) from public.profile_members where user_id='10000000-0000-0000-0000-000000000001'),0::bigint,'B não enumera vínculos privados de A');
select throws_ok($$select public.set_active_profile((select id from test_ids where label='a'))$$,null,'Perfil não autorizado.','B não ativa identidade de A');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
insert into test_ids values('c',public.complete_onboarding('Nome Civil C',((now() at time zone 'America/Sao_Paulo')::date-interval '18 years')::date,true,'Pessoa C','test_c','São Paulo','SP'));
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into test_ids values('invite',public.invite_couple('test_b','Casal Teste','test_couple'));
select is((select count(*) from public.profile_members where profile_type='couple'),0::bigint,'convite não cria casal sem consentimento');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.couple_invitations),0::bigint,'terceiro não vê convites');
select throws_ok($$select public.respond_couple_invitation((select id from test_ids where label='invite'),true)$$,null,'Convite não autorizado.','terceiro não aceita convite');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
insert into test_ids values('couple',public.respond_couple_invitation((select id from test_ids where label='invite'),true));
select is((select count(*) from public.profile_members where profile_type='couple'),2::bigint,'aceite cria exatamente dois integrantes');
select is((select count(*) from public.users_private),1::bigint,'mesmo em casal, parceiro não vê dados civis');
select throws_ok($$select public.respond_couple_invitation((select id from test_ids where label='invite'),true)$$,null,'Convite encerrado ou expirado.','aceite não pode ser repetido');
select throws_ok($$select public.invite_couple('test_c','Outro Casal','test_other')$$,null,'Um dos integrantes já participa de um casal.','impede segundo vínculo de casal');
-- Fixtures de chat inseridas apenas pelo proprietário do banco: não existe criação pública nesta etapa.
reset role;
insert into public.conversations(id) values('20000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002');
insert into public.conversation_members select '20000000-0000-0000-0000-000000000001',id from test_ids where label in('a','c');
insert into public.conversation_members select '20000000-0000-0000-0000-000000000002',id from test_ids where label in('couple','c');
insert into public.messages(conversation_id,sender_profile_id,body) select '20000000-0000-0000-0000-000000000001',id,'Mensagem pessoal A' from test_ids where label='a';
insert into public.messages(conversation_id,sender_profile_id,body) select '20000000-0000-0000-0000-000000000002',id,'Mensagem do casal' from test_ids where label='c';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.messages),0::bigint,'B individual não vê chats do casal nem pessoais de A');
select public.set_active_profile((select id from test_ids where label='couple'));
select is((select count(*) from public.messages),1::bigint,'perfil de casal vê somente conversa do casal');
select is((select count(*) from public.messages where body='Mensagem pessoal A'),0::bigint,'parceiro não lê chat pessoal A');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.messages),1::bigint,'A individual vê apenas conversa individual');
select public.set_active_profile((select id from test_ids where label='couple'));
select is((select count(*) from public.messages where body='Mensagem pessoal A'),0::bigint,'A no casal também não mistura chat individual');
select public.set_active_profile((select id from test_ids where label='a'));
select public.update_profile((select id from test_ids where label='a'),'Pessoa A','','São Paulo','SP','{}','{}','couples');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.profiles where username='test_a'),0::bigint,'individual não vê perfil restrito a casais');
select throws_ok($$select public.update_profile((select id from test_ids where label='a'),'Ataque','','São Paulo','SP','{}','{}','registered')$$,null,'Perfil ativo não autorizado.','terceiro não edita outro perfil');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.profiles where username='test_a'),1::bigint,'casal ativo atende público apenas casais');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.update_profile((select id from test_ids where label='a'),'Pessoa A','','São Paulo','SP','{}','{}','hidden');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.profiles where username='test_a'),0::bigint,'oculto não aparece em consulta de lista');
select is((select count(*) from public.get_profile((select id from test_ids where label='a'))),1::bigint,'oculto das buscas continua acessível por identidade direta');
select throws_ok($$select public.set_profile_avatar((select id from test_ids where label='a'),'other/file.jpg')$$,null,'Perfil ativo não autorizado.','avatar respeita identidade ativa');
reset role;
select is((select public from storage.buckets where id='profile-avatars'),false,'bucket de avatar privado');
reset role;
select is((select count(*) from public.profile_members where profile_id=(select id from test_ids where label='couple')),2::bigint,'nenhuma tentativa criou terceiro integrante');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('users_private','profiles','profile_members','account_context','profile_visibility','couple_invitations','connections','conversations','conversation_members','messages') and not c.relrowsecurity),0::bigint,'RLS em todas as tabelas expostas da etapa');

set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.invitation_partners((select id from test_ids where label='invite'))),0::bigint,'terceiro não lê partes do convite');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select public.leave_couple((select id from test_ids where label='couple'));
select is((select active_profile_id from public.account_context),(select id from test_ids where label='b'),'retirada de consentimento restaura perfil individual');
select is((select count(*) from public.profile_members where profile_type='couple'),0::bigint,'retirada de consentimento encerra acesso compartilhado');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into test_ids values('decline',public.invite_couple('test_b','Novo Casal','test_second'));
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select public.respond_couple_invitation((select id from test_ids where label='decline'),false);
select is((select status from public.couple_invitations where id=(select id from test_ids where label='decline')),'declined','recusa registrada sem criar vínculo');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into test_ids values('cancel',public.invite_couple('test_b','Novo Casal','test_third'));
select public.cancel_couple_invitation((select id from test_ids where label='cancel'));
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.respond_couple_invitation((select id from test_ids where label='cancel'),true)$$,null,'Convite encerrado ou expirado.','convite cancelado não é aceito');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into test_ids values('expired',public.invite_couple('test_b','Novo Casal','test_fourth'));
reset role;
update public.couple_invitations set expires_at=now()-interval '1 second' where id=(select id from test_ids where label='expired');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.respond_couple_invitation((select id from test_ids where label='expired'),true)$$,null,'Convite encerrado ou expirado.','convite expirado não é aceito');
select throws_ok($$update public.account_context set active_profile_id=(select id from test_ids where label='a')$$,'42501',null,'cliente não burla alternância por update direto');
select throws_ok($$insert into public.profile_members(profile_id,user_id,profile_type) values((select id from test_ids where label='a'),'10000000-0000-0000-0000-000000000002','individual')$$,'42501',null,'cliente não forja vínculo direto');
reset role;
set local role anon;
select throws_ok($$select * from public.users_private$$,'42501',null,'anônimo não lê dados privados');
select throws_ok($$select public.get_profile('00000000-0000-0000-0000-000000000000')$$,'42501',null,'anônimo não executa RPC de perfil');
reset role;
select * from finish();
rollback;
